from openai import OpenAI

client = OpenAI()

class Memory:
    def __init__(self):
        self._msgs = []
    def load(self):
        return list(self._msgs)
    def save(self, m):
        self._msgs += m
    def trim(self, n=8):
        self._msgs = self._msgs[-n:]

class Agent:
    def __init__(self, system, tools, memory, max_steps=6):
        self.system = system
        self.tools = tools
        self.memory = memory
        self.max_steps = max_steps

    def run(self, user_msg):
        msgs = [{"role": "system", "content": self.system}] + self.memory.load()
        msgs.append({"role": "user", "content": user_msg})
        for _ in range(self.max_steps):
            reply = client.chat.completions.create(
                model="gpt-4o-mini", messages=msgs, temperature=0
            ).choices[0].message.content
            tool = self._route(reply)
            if not tool:
                self.memory.save([{"role": "user", "content": user_msg},
                                  {"role": "assistant", "content": reply}])
                return reply
            obs = self.tools[tool]()
            msgs.append({"role": "assistant", "content": reply})
            msgs.append({"role": "user", "content": "工具结果：" + obs})
        return reply

    def _route(self, text):
        for name in self.tools:
            if name in text:
                return name
        return ""

if __name__ == "__main__":
    bot = Agent("你是助手", {"查天气": lambda: "北京 25℃晴"}, Memory())
    print(bot.run("帮我查天气"))

# Agent 三层架构：感知 / 决策 / 执行（离线骨架）
class Agent:
    def __init__(self):
        self.tools = {"search": lambda q: f"结果:{q}"}
    def perceive(self, raw):
        return {"input": raw}
    def decide(self, state):
        if "查" in state["input"]:
            return "tool", state["input"]
        return "answer", state["input"]
    def act(self, kind, payload):
        if kind == "tool":
            q = payload.replace("查", "")
            return self.tools["search"](q)
        return f"答：{payload}"

def run(raw):
    a = Agent()
    s = a.perceive(raw)
    k, p = a.decide(s)
    return a.act(k, p)

if __name__ == "__main__":
    print(run("查天气"))
    print(run("你好"))

# 架构演化：单层(直接调LLM) -> 双层(LLM+工具) -> 带记忆(LLM+工具+状态)
def describe(tier):
    if tier == 1:
        return "单层：用户->LLM->回答，无工具无状态"
    if tier == 2:
        return "双层：LLM 决策 + 工具执行，无持久状态"
    return "带记忆：LLM + 工具 + 跨步状态/记忆"

if __name__ == "__main__":
    for t in (1, 2, 3):
        print(f"T{t}: {describe(t)}")

from openai import OpenAI
import re

client = OpenAI()

TOOLS = {
    "搜索": lambda q: "已搜索" + q + " -> 3 条结果",
    "计算器": lambda expr: expr + " = 20",
}

def react(question, max_steps=4):
    trace = "问题：" + question + "\n"
    for _ in range(max_steps):
        prompt = trace + "\n请输出 Thought 与 Action: 工具名(参数)，或 Final Answer: 答案"
        resp = client.chat.completions.create(
            model="gpt-4o-mini",
            messages=[{"role": "user", "content": prompt}],
            temperature=0,
        ).choices[0].message.content
        trace += "\n" + resp
        m = re.search(r"Final Answer:\s*(.+)", resp, re.S)
        if m:
            return m.group(1).strip()
        am = re.search(r"Action:\s*(\w+)\(([^)]*)\)", resp)
        if am:
            name, arg = am.group(1), am.group(2)
            obs = TOOLS.get(name, lambda x: "无此工具")(arg)
            trace += "\nObservation: " + obs
        else:
            trace += "\nObservation: 未识别到 Action，请重新思考"
    return "达到最大步数仍未解决"

if __name__ == "__main__":
    print(react("2 加 3 乘以 4 是多少？"))

# ReAct 范式：Thought -> Action -> Observation 循环（mock LLM 离线）
def mock_llm(prompt):
    if "Observation" in prompt:
        return "Thought: 已有天气，可回答\nAction: finish"
    if "天气" in prompt:
        return 'Thought: 需要查天气\nAction: search["北京"]'
    return "Thought: 已足够回答\nAction: finish"

def parse_action(text):
    if "Action: search" in text:
        return "search", "北京"
    return "finish", ""

def react(question, max_steps=3):
    obs = ""
    for step in range(max_steps):
        out = mock_llm(question + obs)
        kind, _ = parse_action(out)
        if kind == "finish":
            return f"答：关于「{question}」的结论"
        obs = "\nObservation: 北京 25°C"
    return "超时未结束"

if __name__ == "__main__":
    print(react("北京天气"))

