from openai import OpenAI

client = OpenAI()

def plan(goal):
    resp = client.chat.completions.create(
        model="gpt-4o-mini",
        messages=[{"role": "user", "content": "把目标拆成 3 个可执行步骤：" + goal + "。每步一行，只输出步骤。"}],
        temperature=0,
    )
    return [s for s in resp.choices[0].message.content.splitlines() if s.strip()]

def execute(steps):
    results = []
    for i, step in enumerate(steps):
        status = "失败" if i == 1 else "成功"
        results.append((step, status))
        if status == "失败":
            return results
    return results

def run(goal):
    steps = plan(goal)
    results = execute(steps)
    if any(ok == "失败" for _, ok in results):
        results += execute(["重做：" + s for s in plan(goal)])
    return results

if __name__ == "__main__":
    for step, status in run("写一篇产品介绍"):
        print("[" + status + "] " + step)

# Plan-Execute：先出计划，再逐步执行（离线）
def plan(task):
    return [f"步骤{i}:处理「{task}」的子任务{i}" for i in range(1, 3)]

def execute(plan_list):
    done = []
    for step in plan_list:
        done.append(f"✓ {step}")
    return done

if __name__ == "__main__":
    p = plan("写报告")
    print("计划:", p)
    print("执行:", execute(p))

# 动态重规划：某步失败则重新规划剩余（离线）
def execute_with_replan(plan, fail_at):
    done, i = [], 0
    while i < len(plan):
        if i == fail_at:
            plan = plan[:i] + [f"重试步骤{i}"] + plan[i + 1:]
            done.append(f"↻ 在{i}重规划")
        done.append(f"✓ {plan[i]}")
        i += 1
    return done

if __name__ == "__main__":
    print(execute_with_replan(["A", "B", "C"], 1))

