# 记忆：短期(最近N轮) + 长期(摘要)（离线）
class Memory:
    def __init__(self, k=2):
        self.short, self.long, self.k = [], "", k
    def add(self, msg):
        self.short.append(msg)
        if len(self.short) > self.k:
            self.long += f"摘要:{self.short.pop(0)};"
    def view(self):
        return self.long + "|" + " ".join(self.short)

if __name__ == "__main__":
    m = Memory()
    for x in ["A", "B", "C"]:
        m.add(x)
    print(m.view())

# 记忆压缩：超预算时用摘要替换原文（离线）
def compact(items, budget):
    used = 0
    kept = []
    for it in items:
        if used + len(it) <= budget:
            kept.append(it)
            used += len(it)
        else:
            kept.append(f"[摘要]{len(items) - len(kept)}条")
            break
    return kept

if __name__ == "__main__":
    print(compact(["长对话一", "长对话二", "长对话三"], 10))

from pydantic import BaseModel, ValidationError
from openai import OpenAI

client = OpenAI()

class Order(BaseModel):
    product: str
    quantity: int
    address: str

def extract(text, retries=2):
    prompt = "从文本提取订单，只输出 JSON（含 product/quantity/address）：\n" + text
    msgs = [{"role": "user", "content": prompt}]
    for attempt in range(retries + 1):
        resp = client.chat.completions.create(
            model="gpt-4o-mini",
            messages=msgs,
            temperature=0,
            response_format={"type": "json_object"},
        ).choices[0].message.content
        try:
            return Order.model_validate_json(resp)
        except ValidationError as e:
            msgs.append({"role": "assistant", "content": resp})
            msgs.append({"role": "user", "content": "第" + str(attempt + 1) + "次格式错误：" + str(e) + "，请修正后重新输出 JSON。"})
    raise ValueError("重试耗尽仍无法解析")

